import React from "react";

function ConfBar({ value }) {
  const pct = Math.round(value * 100);
  const color = pct >= 90 ? "#ef4444" : pct >= 75 ? "#f59e0b" : "#22c55e";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 4 }}>
      <div style={{ flex: 1, height: 4, background: "#2a2d3a", borderRadius: 2 }}>
        <div style={{ width: `${pct}%`, height: "100%", background: color,
                      borderRadius: 2, transition: "width .3s" }} />
      </div>
      <span style={{ fontSize: 11, color, fontWeight: 600, minWidth: 32 }}>{pct}%</span>
    </div>
  );
}

function AlertRow({ event }) {
  const isCamera = event.type === "camera_alert";
  const time = new Date(event.timestamp).toLocaleTimeString();

  return (
    <div style={{
      padding: "12px 16px", borderBottom: "1px solid #2a2d3a",
      borderLeft: `3px solid ${isCamera ? "#f59e0b" : "#ef4444"}`,
    }}>
      <div style={{ display: "flex", justifyContent: "space-between",
                    alignItems: "flex-start", gap: 8 }}>
        <div>
          <span style={{
            fontSize: 11, fontWeight: 700, letterSpacing: 0.5,
            color: isCamera ? "#f59e0b" : "#ef4444",
          }}>
            {isCamera ? "CAMERA ALERT" : "BOTTLE DETECTED"}
          </span>
          {!isCamera && (
            <div style={{ fontSize: 13, color: "#d1d5db", marginTop: 2 }}>
              {event.class} · {event.brandMatched ? "known alcohol brand" : "unmatched brand"}
            </div>
          )}
          {isCamera && (
            <div style={{ fontSize: 12, color: "#9ca3af", marginTop: 2 }}>
              {event.reason} — luminance: {event.luminance}
            </div>
          )}
        </div>
        <span style={{ fontSize: 11, color: "#6b7280", flexShrink: 0 }}>{time}</span>
      </div>
      {!isCamera && <ConfBar value={event.confidence} />}
    </div>
  );
}

export default function AlertPanel({ alerts }) {
  const card = {
    background: "#1a1d27", borderRadius: 12,
    border: "1px solid #2a2d3a", overflow: "hidden",
    display: "flex", flexDirection: "column",
  };

  return (
    <div style={card}>
      <div style={{ padding: "12px 16px", borderBottom: "1px solid #2a2d3a",
                    display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: "#9ca3af", letterSpacing: 0.5 }}>
          ALERT LOG
        </span>
        <span style={{ fontSize: 11, color: "#6b7280" }}>{alerts.length} events</span>
      </div>

      <div style={{ overflowY: "auto", maxHeight: 480 }}>
        {alerts.length === 0 ? (
          <div style={{ padding: 32, textAlign: "center", color: "#4b5563", fontSize: 13 }}>
            No alerts yet — monitoring active
          </div>
        ) : (
          alerts.map(a => <AlertRow key={a.id} event={a} />)
        )}
      </div>
    </div>
  );
}
